SELECT p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.icustay_id, pr.procedure_code, pr.procedure_name, COUNT(DISTINCT i.icustay_id) AS patient_count, MIN(i.icustay_id) AS min_icustay_id, MAX(i.icustay_id) AS max_icustay_id, AVG(i.icustay_id) AS avg_icustay_id, AVG(i.length_of_stay) AS avg_length_of_stay, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END) AS mortality_count FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN procedures_icd pr ON i.hadm_id = pr.subject_id AND i.stay_id = pr.hadm_id WHERE p.gender = 'M' AND p.anchor_age = 95 AND p.anchor_year BETWEEN 90 AND 100 AND i.first_careunit = 'ICU' AND i.hadm_id IN (SELECT hadm_id FROM diagnoses_icd WHERE icd_code = '448') AND i.stay_id IN (SELECT stay_id FROM chartevents WHERE charttime BETWEEN i.intime AND i.outtime AND itemid IN (SELECT itemid FROM d_items WHERE category = 'Procedure')) GROUP BY p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, i.icustay_id, pr.procedure_code, pr.procedure_name ORDER BY patient_count DESC, min_icustay_id ASC, max_icustay_id ASC, avg_icustay_id ASC, avg_length_of_stay ASC, mortality_count ASC;